model discussion_board_admin_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Administrator who owns this session. {@link discussion_board_admins.id}
  discussion_board_admin_id String @db.Uuid

  /// IP address from which the admin logged in, captured for security auditing
  /// and session validation.
  ip String

  /// URL path the admin was accessing when the session was created, useful for
