  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  memberSessions discussion_board_member_sessions[]
  passwordResets discussion_board_member_password_resets[]
  auditLogs      discussion_board_admin_audit_logs[]
