  memberComments discussion_board_comments[]
  adminRequests  discussion_board_admin_requests[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([created_at])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Member login sessions tracking JWT authentication with connection
