export async function test_api_guest_join_new_device(
  connection: api.IConnection,
): Promise<void> {
  // Generate unique device fingerprint for this guest
  const deviceFingerprint = RandomGenerator.alphaNumeric(32);
  // Create a new connection for guest actor (connection isolation pattern)
  const guestConnection: api.IConnection = { host: connection.host };
  // Join as a new guest with unique device fingerprint
  const authorized = await authorize_guest_join(guestConnection, {
    body: {
      device_fingerprint: deviceFingerprint,
      href: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // Validate complete response structure (id, token with all fields)
  typia.assert(authorized);
  // Verify connection is now authenticated with access token
  TestValidator.predicate(
    "guest connection has authorization header",
    guestConnection.headers?.Authorization !== undefined,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

export async function test_api_guest_join_returning_device(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create first guest connection and join with specific device fingerprint
  const firstConnection: api.IConnection = { host: connection.host };
  const deviceFingerprint = RandomGenerator.alphaNumeric(32);
  const firstHref = "https://example.com/page1";
  const firstGuest = await authorize_guest_join(firstConnection, {
    body: {
      device_fingerprint: deviceFingerprint,
      href: firstHref,
    },
  });
  typia.assert(firstGuest);
  // Step 2: Store the first guest's information
  const firstGuestId = firstGuest.id;
  const firstAccessToken = firstGuest.token.access;
  const firstRefreshToken = firstGuest.token.refresh;
  // Step 3: Create second guest connection with same device fingerprint but different href
  const secondConnection: api.IConnection = { host: connection.host };
  const secondHref = "https://example.com/page2";
  const secondGuest = await authorize_guest_join(secondConnection, {
    body: {
      device_fingerprint: deviceFingerprint,
      href: secondHref,
    },
  });
  typia.assert(secondGuest);
  // Step 4: Validate tokens are different (new session created)
  TestValidator.notEquals(
    "access tokens differ",
    firstAccessToken,
    secondGuest.token.access,
  );
  TestValidator.notEquals(
    "refresh tokens differ",
    firstRefreshToken,
    secondGuest.token.refresh,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

export async function test_api_guest_join_full_metadata(
  connection: api.IConnection,
): Promise<void> {
  // Test 1: Full metadata with all fields provided
  const fullMetadataJoin = await authorize_guest_join(connection, {
    body: {
      device_fingerprint: RandomGenerator.alphaNumeric(32),
      href: "https://discussion.example.com/sections/politics",
      referrer: "https://google.com/search?q=politics",
      ip: "192.168.1.100",
    } satisfies IDiscussionBoardGuest.IJoin,
  });
  typia.assert(fullMetadataJoin);
  TestValidator.predicate("has valid UUID id", () =>
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      fullMetadataJoin.id,
    ),
  );
  TestValidator.predicate(
    "has access token",
    () =>
      typeof fullMetadataJoin.token.access === "string" &&
      fullMetadataJoin.token.access.length > 0,
  );
  TestValidator.predicate(
    "has refresh token",
    () =>
      typeof fullMetadataJoin.token.refresh === "string" &&
      fullMetadataJoin.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "has valid expired_at timestamp",
    () => !isNaN(new Date(fullMetadataJoin.token.expired_at).getTime()),
  );
  TestValidator.predicate(
    "has valid refreshable_until timestamp",
    () => !isNaN(new Date(fullMetadataJoin.token.refreshable_until).getTime()),
  );
  // Test 2: Nullable referrer (direct visit, no referrer)
  const nullReferrerJoin = await authorize_guest_join(connection, {
    body: {
      device_fingerprint: RandomGenerator.alphaNumeric(32),
      href: "https://discussion.example.com/sections/economics",
      referrer: null,
      ip: "10.0.0.50",
    } satisfies IDiscussionBoardGuest.IJoin,
  });
  typia.assert(nullReferrerJoin);
  TestValidator.notEquals(
    "different guest id for null referrer",
    fullMetadataJoin.id,
    nullReferrerJoin.id,
  );
  // Test 3: Server-extracted IP (when client omits ip field)
  const noClientIpJoin = await authorize_guest_join(connection, {
    body: {
      device_fingerprint: RandomGenerator.alphaNumeric(32),
      href: "https://discussion.example.com/sections/technology",
      referrer: "https://twitter.com/trending",
    } satisfies IDiscussionBoardGuest.IJoin,
  });
  typia.assert(noClientIpJoin);
  TestValidator.notEquals(
    "different guest id for no client IP",
    fullMetadataJoin.id,
    noClientIpJoin.id,
  );
  // Test 4: Minimum required fields only (device_fingerprint and href)
  const minimalJoin = await authorize_guest_join(connection, {
    body: {
      device_fingerprint: RandomGenerator.alphaNumeric(32),
      href: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardGuest.IJoin,
  });
  typia.assert(minimalJoin);
  TestValidator.notEquals(
    "different guest id for minimal join",
    fullMetadataJoin.id,
    minimalJoin.id,
  );
}

