import { MyGlobal } from "../MyGlobal";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { DiscussionBoardAdminRequestTransformer } from "../transformers/DiscussionBoardAdminRequestTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postDiscussionBoardAdminAdminRequestsAdminRequestIdApprove(props: {
  admin: AdminPayload;
  adminRequestId: string & tags.Format<"uuid">;
}): Promise<IDiscussionBoardAdminRequest> {
  // 1. Authorization - verify super admin
  const currentAdmin =
    await MyGlobal.prisma.discussion_board_admins.findUniqueOrThrow({
      where: { id: props.admin.id },
      select: { id: true, grade: true },
    });
  if (currentAdmin.grade !== "super") {
    throw new HttpException(
      "Only super administrators can approve requests",
      403,
    );
  }
  // 2. Fetch request with member data for validation
  const request =
    await MyGlobal.prisma.discussion_board_admin_requests.findUnique({
      where: { id: props.adminRequestId },
      select: {
        id: true,
        status: true,
        deleted_at: true,
        member: {
          select: {
            id: true,
            email: true,
            password_hash: true,
            display_name: true,
            bio: true,
            banned: true,
          },
        },
      },
    });
  if (request === null) {
    throw new HttpException("Admin request not found", 404);
  }
  if (request.deleted_at !== null) {
    throw new HttpException("Admin request has been deleted", 410);
  }
  if (request.status !== "pending") {
    throw new HttpException("Request is not in pending status", 400);
  }
  if (request.member.banned) {
    throw new HttpException("Requesting member is banned", 400);
  }
  // 3. Execute approval in transaction with optimistic locking
  const now = new Date();
  const approvalResult = await MyGlobal.prisma.$transaction(async (tx) => {
    // Atomic update with status check (optimistic locking)
    const updateResult = await tx.discussion_board_admin_requests.updateMany({
      where: {
        id: props.adminRequestId,
        status: "pending",
      },
      data: {
        status: "approved",
        admin_id: props.admin.id,
        updated_at: now,
      },
    });
    if (updateResult.count === 0) {
      return null; // Request was already processed
    }
    // Create admin record (upsert to handle edge case of existing admin)
    await tx.discussion_board_admins.upsert({
      where: { email: request.member.email },
      create: {
        id: v4(),
        email: request.member.email,
        password_hash: request.member.password_hash,
        display_name: request.member.display_name,
        bio: request.member.bio,
        grade: "regular",
        banned_at: null,
        ban_reason: null,
        created_at: now,
        updated_at: now,
        deleted_at: null,
      },
      update: {
        grade: "regular",
        deleted_at: null,
        updated_at: now,
      },
    });
    return { success: true };
  });
  if (approvalResult === null) {
    throw new HttpException("Request has already been processed", 409);
  }
  // 4. Fetch and return updated request with full relations
  const updated =
    await MyGlobal.prisma.discussion_board_admin_requests.findUniqueOrThrow({
      where: { id: props.adminRequestId },
      ...DiscussionBoardAdminRequestTransformer.select(),
    });
  return await DiscussionBoardAdminRequestTransformer.transform(updated);
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postDiscussionBoardAuthAdminLogin(props: {
  body: IDiscussionBoardAdmin.ILogin;
}): Promise<IDiscussionBoardAdmin.IAuthorized> {
  // 1. Find admin by email with password_hash
  const admin = await MyGlobal.prisma.discussion_board_admins.findFirst({
    where: { email: props.body.email },
    select: {
      id: true,
      email: true,
      password_hash: true,
      display_name: true,
      bio: true,
      grade: true,
      banned_at: true,
      ban_reason: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });
  // Generic error to prevent email enumeration
  if (!admin) {
    throw new HttpException("Invalid credentials", 401);
  }
  // Store banned_at and deleted_at BEFORE validation checks to avoid control flow narrowing
  const bannedAt = admin.banned_at;
  const deletedAt = admin.deleted_at;
  // 2. Verify password
  const isValid = await PasswordUtil.verify(
    props.body.password,
    admin.password_hash,
  );
  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }
  // 3. Check account status - soft-deleted accounts cannot authenticate
  if (deletedAt !== null) {
    throw new HttpException("Account has been deleted", 401);
  }
  // Banned accounts cannot authenticate
  if (bannedAt !== null) {
    throw new HttpException(
      admin.ban_reason !== null
        ? `Account is banned: ${admin.ban_reason}`
        : "Account is banned",
      403,
    );
  }
  // 4. Enforce single session policy - delete existing sessions
  await MyGlobal.prisma.discussion_board_admin_sessions.deleteMany({
    where: { discussion_board_admin_id: admin.id },
  });
  // 5. Create new session
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000); // 1 hour
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 days
  const session = await MyGlobal.prisma.discussion_board_admin_sessions.create({
    data: {
      id: v4(),
      discussion_board_admin_id: admin.id,
      ip: props.body.ip ?? "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: accessExpires,
    },
  });
  // 6. Generate JWT tokens
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };
  // 7. Return IAuthorized
  return {
    id: admin.id,
    email: admin.email,
    displayName: admin.display_name,
    bio: admin.bio,
    grade: typia.assert<"regular" | "super">(admin.grade),
    bannedAt: bannedAt !== null ? toISOStringSafe(bannedAt) : null,
    banReason: admin.ban_reason,
    createdAt: toISOStringSafe(admin.created_at),
    updatedAt: toISOStringSafe(admin.updated_at),
    deletedAt: deletedAt !== null ? toISOStringSafe(deletedAt) : null,
    token,
  } satisfies IDiscussionBoardAdmin.IAuthorized;
}

